def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    danger_bids = []
    rich_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                    danger_bids.append(b)

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    danger_prev = max(danger_bids) if danger_bids else highest_prev

    severe_need = hp <= 2 or no_water >= 2
    urgent_need = hp <= 4 or no_water >= 1
    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    remaining_days = max(0, 10 - int(day) + 1)
    reserve_target = max(0.0, remaining_days * 18.0)
    spendable = max(0.0, budget - reserve_target)

    if severe_need:
        bid = max(68.0, danger_prev + 4.0, highest_prev + 2.0)
    elif urgent_need and tight_supply:
        bid = max(58.0, danger_prev + 2.5, avg_prev + 3.0)
    elif tight_supply:
        bid = max(32.0, min(62.0, highest_prev + 1.5))
    elif loose_supply:
        bid = 12.0 if hp >= 7 and no_water == 0 else 22.0
    else:
        bid = max(20.0, min(48.0, avg_prev * 0.55 + 6.0))

    if rich_count >= 2 and not urgent_need:
        bid -= 4.0
    if desperate_count >= 2 and not severe_need:
        bid += 5.0
    if budget < DAILY_SALARY:
        bid = min(bid, max(12.0, budget * 0.72))
    elif spendable > 0 and not urgent_need:
        bid = min(bid, 20.0 + spendable * 0.25)

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # If we can't pay much, still try to extend survival.
    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        # No contest: bid as low as possible while keeping some chance.
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Read yesterday bids from immediate trace only.
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If someone previously overpaid, they likely continue pressure; undercut slightly.
    very_aggressive = highest_prev_bid >= DAILY_SALARY * 1.3  # >=117

    # Base bid: aim to secure enough water without burning budget.
    # Use our hp/no_water_days to decide urgency.
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # Adjust using yesterday aggressiveness.
    if very_aggressive:
        # Undercut the highest previous bid by a small margin.
        target = min(base, highest_prev_bid * 0.85)
    else:
        # If no one was too aggressive, slightly increase to secure allocation.
        target = max(base, DAILY_SALARY * 0.5)

    # Supply awareness: if supply is near minimum, competition is tighter -> bid a bit more.
    if supply <= 17.0:
        target *= 1.15
    elif supply >= 22.0:
        target *= 0.95

    # Ensure we don't exceed budget.
    target = max(0.0, min(float(budget), float(target)))

    # If budget is extremely low, bid whatever we can.
    if budget <= 1.0:
        return max(0.0, float(budget))

    # Final clamp: avoid wasting money far above typical scale.
    max_reasonable = DAILY_SALARY * 1.05
    if target > max_reasonable:
        target = max_reasonable

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if not prev_bids:
        bid = DAILY_SALARY * 0.4
    else:
        avg_prev = sum(prev_bids) / len(prev_bids)
        if my_status['hp'] < 4:
            bid = min(my_status['budget'], avg_prev * 1.1)
        else:
            bid = min(my_status['budget'], avg_prev * 0.8)

    if day_context['supply'] > 20:
        bid = min(bid, DAILY_SALARY * 0.3)

    return float(max(1.0, min(my_status['budget'], bid)))
